CREATE COLUMN TABLE "TEST_AP"."ORCI" ("Code" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(30), "Active" NVARCHAR(1) DEFAULT 'Y', "IsMultiple" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "UserSign2" NVARCHAR(6), PRIMARY KEY ("Code")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ORCI_NAME" ON "TEST_AP"."ORCI" ( "Name" ASC )